const {chromium} = require(process.env.FLEET_PLAYWRIGHT_MODULE);
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const [origin, viewport] = process.argv.slice(2);
(async () => {
  const browser = await chromium.launch({channel:process.env.FLEET_BROWSER_CHANNEL || 'chrome',headless:true});
  try {
    const context = await browser.newContext({viewport:{width:viewport === 'mobile' ? 390 : 1440,height:1000}});
    const page = await context.newPage(), errors=[]; page.setDefaultTimeout(10000);
    page.on('pageerror', error => errors.push(error.message));
    await page.route('**/api/operator/session', async route => {
      const response=await route.fetch(), body=await response.json();
      await route.fulfill({response,json:{...body,authenticated:true,user:{id:'browser@example.test',role:'admin',name:'Browser'}}});
    });
    const settle = async state => { const response=await context.request.post(origin+'/_fixture/settle-account',{data:{state}}); assert.equal(response.status(),200); assert.ok((await response.json()).count>0); };
    const admit = async control => {const response=page.waitForResponse(row=>row.request().method()==='POST'&&row.url().includes('/provider-accounts')&&row.ok());await control.click();await response;};
    const refresh = () => page.getByRole('button',{name:'刷新账号状态',exact:true}).click();
    await page.goto(origin+'/settings/provider-accounts');
    await page.getByText('此节点还没有独立 Google 账号。创建后可发起登录。',{exact:true}).waitFor();
    assert.equal(await page.getByLabel('电脑节点',{exact:true}).inputValue(),'mac-local');
    let creates=[];
    const lostCreate=async route=>{creates.push(route.request().postDataJSON()); await route.fetch(); await route.abort('failed');};
    await page.route('**/api/machines/mac-local/provider-accounts',async route=> route.request().method()==='POST' ? lostCreate(route) : route.continue());
    await page.getByLabel('账号名称',{exact:true}).fill('Google work <img src=x>');
    await page.getByRole('button',{name:'创建独立账号',exact:true}).click();
    await page.getByText('原请求结果待确认',{exact:true}).waitFor();
    await page.reload();
    await page.getByText('原请求结果待确认',{exact:true}).waitFor();
    await page.unroute('**/api/machines/mac-local/provider-accounts');
    await page.route('**/api/machines/mac-local/provider-accounts',async route=>{if(route.request().method()==='POST')creates.push(route.request().postDataJSON()); await route.continue();});
    await page.getByRole('button',{name:'恢复原账号操作',exact:true}).click();
    const card=page.locator('.provider-account-card').filter({has:page.getByRole('heading',{name:'Google work <img src=x>',exact:true})}); await card.waitFor();
    assert.equal(creates.length,2); assert.deepEqual(creates[0],creates[1]);
    assert.equal(await page.locator('.provider-account-card').count(),1);
    assert.equal(await card.locator('img,script').count(),0);
    await settle('signed_out'); await refresh();
    await admit(card.getByRole('button',{name:'登录',exact:true}));
    await settle('waiting'); await refresh();
    await card.getByRole('link',{name:'打开 Google 授权页面',exact:true}).waitFor();
    const link=await card.getByRole('link',{name:'打开 Google 授权页面',exact:true}).getAttribute('href'); assert.equal(new URL(link).host,'accounts.google.com');
    await card.getByLabel('授权结果 · Google work <img src=x>',{exact:true}).fill('fixture-private-code');
    await refresh(); assert.equal(await card.locator('input[type=password]').inputValue(),'fixture-private-code');
    await page.route('**/api/machines/mac-local/provider-accounts',route=>route.fulfill({status:503,json:{ok:false,error:'provider_accounts_unavailable'}}));
    await refresh(); await page.getByText(/账号存储暂不可用/).waitFor();
    assert.equal(await card.getByText(/授权窗口已过期/).count(),0);
    await page.unroute('**/api/machines/mac-local/provider-accounts'); await refresh();
    await card.locator('input[type=password]').waitFor();
    assert.equal(await card.locator('input[type=password]').inputValue(),'fixture-private-code');
    let submissions=[];
    await page.route('**/api/provider-accounts/*/operations',async route=>{
      const body=route.request().postDataJSON(); if(body.operation==='submit_login') {submissions.push(body); await route.fetch(); await route.abort('failed');} else await route.continue();
    });
    await card.getByRole('button',{name:'提交授权结果',exact:true}).click();
    await page.getByText('原请求结果待确认',{exact:true}).waitFor();
    assert.equal(await page.evaluate(()=>JSON.stringify(sessionStorage).includes('fixture-private-code')),false);
    await page.reload(); await page.getByLabel('原授权结果',{exact:true}).fill('fixture-private-code');
    await refresh(); assert.equal(await page.getByLabel('原授权结果',{exact:true}).inputValue(),'fixture-private-code');
    await page.unroute('**/api/provider-accounts/*/operations');
    await page.route('**/api/provider-accounts/*/operations',async route=>{const body=route.request().postDataJSON();if(body.operation==='submit_login')submissions.push(body);await route.continue();});
    await page.getByRole('button',{name:'恢复原账号操作',exact:true}).click();
    await page.getByText('请求已受理，正在等待节点更新账号状态。',{exact:true}).waitFor();
    assert.deepEqual(submissions[0],submissions[1]);
    await settle('ready'); await refresh(); await card.getByText('可用',{exact:true}).waitFor();
    const accountId=await card.locator('p.meta').first().innerText();
    // Login and cancellation of B must leave the ready account A untouched.
    await page.getByLabel('账号名称',{exact:true}).fill('Google personal');
    await admit(page.getByRole('button',{name:'创建独立账号',exact:true}));
    await settle('signed_out'); await refresh();
    const personal=page.locator('.provider-account-card').filter({has:page.getByRole('heading',{name:'Google personal',exact:true})});
    await admit(personal.getByRole('button',{name:'登录',exact:true}));
    await settle('waiting'); await refresh();
    await personal.getByRole('link',{name:'打开 Google 授权页面',exact:true}).waitFor();
    await admit(personal.getByRole('button',{name:'取消本次登录',exact:true}));
    await settle('signed_out'); await refresh();
    await personal.getByText('未登录',{exact:true}).waitFor();
    await card.getByText('可用',{exact:true}).waitFor();
    if(process.env.FLEET_SCREENSHOTS){await fs.mkdir(process.env.FLEET_SCREENSHOTS,{recursive:true});await page.screenshot({path:process.env.FLEET_SCREENSHOTS+'/google-accounts-'+viewport+'.png',fullPage:true});}
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
    await page.goto(origin+'/assistant?view=computer&machine=mac-local');
    const google=page.getByLabel('Google 账号',{exact:true}); await google.waitFor();
    await google.selectOption(accountId);
    await page.route('**/api/machines/mac-local/provider-accounts',route=>route.fulfill({status:503,json:{ok:false,error:'provider_accounts_unavailable'}}));
    await page.getByRole('button',{name:'刷新 Google 账号',exact:true}).click();
    await page.getByText(/Google 账号目录读取失败，发送已暂停/).waitFor();
    assert.equal(await google.inputValue(),accountId);
    assert.equal(await page.getByRole('button',{name:'发送给电脑 Agent',exact:true}).isDisabled(),true);
    await page.unroute('**/api/machines/mac-local/provider-accounts');
    await page.getByRole('button',{name:'刷新 Google 账号',exact:true}).click();
    await page.waitForFunction(()=>!document.querySelector('select[aria-label="Google 账号"]').disabled);
    assert.equal(await google.inputValue(),accountId);
    const toggle=async(operation,state,clientToken)=>{
      const response=await context.request.post(origin+'/api/provider-accounts/'+accountId+'/operations',{data:{operation,client_token:clientToken}});
      assert.equal(response.status(),202); await settle(state);
      await page.getByRole('button',{name:'刷新 Google 账号',exact:true}).click();
      await page.waitForFunction(({id,state})=>[...document.querySelectorAll('select[aria-label="Google 账号"] option')].some(option=>option.value===id&&option.textContent.includes(state)),{id:accountId,state:state==='ready'?'可用':'已禁用'});
    };
    await toggle('disable','disabled','fixture-before-disable');
    assert.equal(await google.inputValue(),accountId);
    await page.getByLabel('给电脑 Agent 的消息',{exact:true}).fill('Inspect bound workspace');
    assert.equal(await page.getByRole('button',{name:'发送给电脑 Agent',exact:true}).isDisabled(),true);
    await toggle('enable','ready','fixture-before-enable');
    let taskBodies=[];
    await page.route('**/api/tasks',async route=> {if(route.request().method()==='POST'){taskBodies.push(route.request().postDataJSON()); await route.fetch();await route.abort('failed');}else await route.continue();});
    await page.getByLabel('给电脑 Agent 的消息',{exact:true}).fill('Inspect bound workspace');
    await page.getByRole('button',{name:'发送给电脑 Agent',exact:true}).click();
    await page.getByRole('button',{name:'查询或重试同一启动',exact:true}).waitFor();
    assert.equal(taskBodies[0].provider_account_id,accountId);
    // Readiness may change after acceptance; recovery still uses the original account.
    const disable=await context.request.post(origin+'/api/provider-accounts/'+accountId+'/operations',{data:{operation:'disable',client_token:'fixture-disable'}});assert.equal(disable.status(),202);
    await settle('disabled'); await page.reload(); await page.unroute('**/api/tasks');
    await page.route('**/api/tasks',async route=>{if(route.request().method()==='POST')taskBodies.push(route.request().postDataJSON());await route.continue();});
    await page.getByRole('button',{name:'查询或重试同一启动',exact:true}).click();
    await page.waitForURL(/\/task\/.+\?view=chat/);
    assert.deepEqual(taskBodies[0],taskBodies[1]);
    assert.equal((await (await context.request.get(origin+'/api/tasks')).json()).tasks.length,1);
    // Directory refresh never silently switches an explicitly selected disabled account.
    await page.goto(origin+'/assistant?view=computer&machine=mac-local');
    await page.getByLabel('Google 账号',{exact:true}).waitFor();
    await page.getByLabel('Agent',{exact:true}).selectOption('codex');
    assert.equal(await google.isVisible(),false);
    await page.goto(origin+'/settings/provider-accounts');
    await card.locator('summary').filter({hasText:'退出此账号登录'}).click();
    await admit(card.getByRole('button',{name:'确认退出 Google 登录',exact:true}));
    await settle('signed_out'); await refresh(); await card.getByText('未登录',{exact:true}).waitFor();
    await admit(card.getByRole('button',{name:'启用',exact:true}));
    await settle('signed_out'); await refresh(); await card.getByRole('button',{name:'登录',exact:true}).waitFor();
    await page.getByLabel('电脑节点',{exact:true}).selectOption('legacy');
    await page.getByText(/此节点尚未上报在线 AGY 多账号能力/).waitFor();
    assert.equal(await page.getByRole('button',{name:'创建独立账号',exact:true}).isDisabled(),true);
    await page.getByLabel('账号名称',{exact:true}).fill('Unsupported keyboard submission');
    await page.getByLabel('账号名称',{exact:true}).press('Enter');
    assert.equal(await page.getByText('原请求结果待确认',{exact:true}).count(),0);
    assert.deepEqual(errors,[]); await context.close();
  } finally {await browser.close();}
})().catch(error=>{console.error(error);process.exit(1)});
